<script lang="ts">
 import {onMount} from 'svelte';import {locale,t} from '$lib/i18n';
 let rows=$state<any[]>([]),email=$state(''),days=$state(7),code=$state(''),error=$state(''),busy=$state(false);
 async function load(){const r=await fetch('/api/v1/users/invitations');if(r.ok)rows=await r.json();}
 async function create(){busy=true;error='';code='';try{const r=await fetch('/api/v1/users/invitations',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:email||null,valid_days:days})});const d=await r.json();if(!r.ok)throw Error(typeof d.detail==='string'?d.detail:'Could not create invitation.');code=d.code;await load();}catch(e){error=(e as Error).message;}finally{busy=false;}}
 async function revoke(id:string){const r=await fetch('/api/v1/users/invitations/'+id,{method:'DELETE'});if(r.ok)await load();}
 onMount(load);
</script>
<section class="mt-6 space-y-4 rounded-xl border p-4"><h3 class="text-xl font-semibold">{t($locale,'Invitations')}</h3><p class="text-sm text-muted-foreground">{t($locale,'Registration requires a single-use invitation code and email confirmation. Codes are displayed once.')}</p><div class="grid gap-3 sm:grid-cols-2"><label class="text-sm">{t($locale,'Bind to email (optional)')}<input type="email" bind:value={email} class="mt-1 w-full rounded-lg border bg-background p-2"/></label><label class="text-sm">{t($locale,'Valid for days')}<input type="number" min="1" max="30" bind:value={days} class="mt-1 w-full rounded-lg border bg-background p-2"/></label></div><button disabled={busy} onclick={create} class="rounded-lg bg-primary px-4 py-2 text-primary-foreground">{t($locale,'Create invitation')}</button>{#if code}<p role="status" class="rounded-lg border border-primary p-4 text-2xl font-mono tracking-widest">{code}</p>{/if}{#if error}<p role="alert" class="text-sm text-destructive">{t($locale,error)}</p>{/if}<div class="space-y-2">{#each rows as row}<article class="flex flex-wrap items-center justify-between gap-2 rounded-lg border p-3 text-sm"><span>{row.email||t($locale,'Any email')} · {new Date(row.expires_at).toLocaleDateString($locale)} · {t($locale,row.used_at?'Used':row.revoked?'Revoked':new Date(row.expires_at)<new Date()?'Expired':'Available')}</span>{#if !row.used_at&&!row.revoked}<button onclick={()=>revoke(row.id)} class="rounded border px-2 py-1">{t($locale,'Revoke')}</button>{/if}</article>{/each}</div></section>
